def parse_duration(text):
    if not text:
        raise ValueError("empty string")

    units = {'d': 86400, 'h': 3600, 'm': 60, 's': 1}
    seen = set()
    total = 0
    i = 0
    n = len(text)

    while i < n:
        # skip spaces
        while i < n and text[i] == ' ':
            i += 1
        if i >= n:
            break

        # parse number
        start = i
        while i < n and text[i].isdigit():
            i += 1
        if start == i:
            raise ValueError("missing number")
        num_str = text[start:i]
        # no leading zeros? not required but reject negative? already positive digits
        # parse integer
        num = int(num_str)
        if num <= 0:
            raise ValueError("non-positive number")

        # skip spaces between number and unit
        while i < n and text[i] == ' ':
            i += 1
        if i >= n:
            raise ValueError("missing unit")

        unit = text[i]
        if unit not in units:
            raise ValueError("unknown unit")
        if unit in seen:
            raise ValueError("duplicate unit")
        seen.add(unit)

        total += num * units[unit]
        i += 1

    if not seen:
        raise ValueError("no units found")

    # check trailing junk (non-space, non-digit already handled)
